from __future__ import annotations

from typing import Iterable


def weighted_composite(
    scores: dict[str, float | int | None],
    weights: dict[str, float],
) -> float | None:
    """Paper Eq. (1): MMMU-weighted average over valid VLM scores (>0)."""
    num = 0.0
    den = 0.0
    for model, score in scores.items():
        if score is None:
            continue
        s = float(score)
        if s <= 0:
            continue
        w = weights.get(model, 1.0)
        num += s * w
        den += w
    if den == 0:
        return None
    return num / den


def normalize_vlm_keys(row: dict) -> dict[str, float | int | None]:
    mapping = {
        "qwen25vl3b": row.get("qwen25vl3b"),
        "llama32vl11b": row.get("llama32vl11b"),
        "aya_vision_8b": row.get("aya_vision_8b"),
    }
    return {k: (int(v) if v is not None and v != "" else None) for k, v in mapping.items()}


def recompute_composite(row: dict, weights: dict[str, float]) -> float | None:
    return weighted_composite(normalize_vlm_keys(row), weights)


def score_distribution(values: Iterable[float | int]) -> dict[int, int]:
    dist: dict[int, int] = {i: 0 for i in range(7)}
    for v in values:
        if v is None:
            continue
        bucket = max(0, min(6, int(round(float(v)))))
        dist[bucket] += 1
    return dist

from __future__ import annotations

import base64
import os
from pathlib import Path
from typing import Literal

import httpx

Provider = Literal["openai", "ollama"]


class LLMClient:
    def __init__(
        self,
        model: str,
        provider: Provider = "openai",
        base_url: str | None = None,
        api_key: str | None = None,
    ):
        self.model = model
        self.provider = provider
        self.base_url = (base_url or os.getenv("OPENAI_BASE_URL", "https://api.openai.com/v1")).rstrip("/")
        self.api_key = api_key or os.getenv("OPENAI_API_KEY", "")
        self.ollama_url = os.getenv("OLLAMA_BASE_URL", "http://localhost:11434").rstrip("/")

    def chat(self, system: str, user: str, temperature: float = 0.7) -> str:
        if self.provider == "ollama":
            return self._ollama_chat(system, user, temperature)
        return self._openai_chat(system, user, temperature)

    def vision_score(self, image_path: Path, prompt: str) -> int:
        if self.provider == "ollama":
            return self._ollama_vision(image_path, prompt)
        return self._openai_vision(image_path, prompt)

    def _openai_chat(self, system: str, user: str, temperature: float) -> str:
        headers = {"Authorization": f"Bearer {self.api_key}"}
        payload = {
            "model": self.model,
            "temperature": temperature,
            "messages": [
                {"role": "system", "content": system},
                {"role": "user", "content": user},
            ],
        }
        with httpx.Client(timeout=300) as client:
            r = client.post(f"{self.base_url}/chat/completions", headers=headers, json=payload)
            r.raise_for_status()
            return r.json()["choices"][0]["message"]["content"].strip()

    def _ollama_chat(self, system: str, user: str, temperature: float) -> str:
        payload = {
            "model": self.model,
            "stream": False,
            "options": {"temperature": temperature},
            "messages": [
                {"role": "system", "content": system},
                {"role": "user", "content": user},
            ],
        }
        with httpx.Client(timeout=600) as client:
            r = client.post(f"{self.ollama_url}/api/chat", json=payload)
            r.raise_for_status()
            return r.json()["message"]["content"].strip()

    def _openai_vision(self, image_path: Path, prompt: str) -> int:
        b64 = base64.b64encode(image_path.read_bytes()).decode()
        headers = {"Authorization": f"Bearer {self.api_key}"}
        payload = {
            "model": self.model,
            "temperature": 0,
            "messages": [
                {
                    "role": "user",
                    "content": [
                        {"type": "text", "text": prompt},
                        {
                            "type": "image_url",
                            "image_url": {"url": f"data:image/png;base64,{b64}"},
                        },
                    ],
                }
            ],
        }
        with httpx.Client(timeout=300) as client:
            r = client.post(f"{self.base_url}/chat/completions", headers=headers, json=payload)
            r.raise_for_status()
            text = r.json()["choices"][0]["message"]["content"].strip()
        return _parse_score(text)

    def _ollama_vision(self, image_path: Path, prompt: str) -> int:
        b64 = base64.b64encode(image_path.read_bytes()).decode()
        payload = {
            "model": self.model,
            "stream": False,
            "messages": [
                {
                    "role": "user",
                    "content": prompt,
                    "images": [b64],
                }
            ],
        }
        with httpx.Client(timeout=600) as client:
            r = client.post(f"{self.ollama_url}/api/chat", json=payload)
            r.raise_for_status()
            text = r.json()["message"]["content"].strip()
        return _parse_score(text)


def _parse_score(text: str) -> int:
    for token in text.replace(".", " ").split():
        if token.isdigit():
            val = int(token)
            if 0 <= val <= 6:
                return val
    return 0


def provider_from_env() -> Provider:
    return "ollama" if os.getenv("USE_OLLAMA", "").lower() in ("1", "true", "yes") else "openai"

from __future__ import annotations

import json
import uuid
from pathlib import Path
from typing import Any

import pandas as pd
from tqdm import tqdm

from uml_pipeline.llm_client import LLMClient, provider_from_env
from uml_pipeline.prompts import (
    PLANTUML_CODE_PROMPT,
    PLANTUML_DIAGRAM_HINTS,
    SPEC_USER_PROMPT,
    SYSTEM_ARCHITECT_PROMPT,
    VLM_SCORING_PROMPT,
)
from uml_pipeline.render import render_plantuml
from uml_pipeline.scoring import weighted_composite


def generate_spec(
    client: LLMClient,
    diagram_type: str,
    mode: str = "architect",
) -> str:
    if mode == "user":
        return client.chat(
            "You generate realistic software feature descriptions.",
            SPEC_USER_PROMPT,
            temperature=0.8,
        )
    user = (
        f"Create a technical specification for a {diagram_type} UML diagram "
        f"for a realistic software system feature."
    )
    return client.chat(SYSTEM_ARCHITECT_PROMPT, user, temperature=0.8)


def generate_plantuml(client: LLMClient, specification: str, diagram_type: str) -> str:
    hint = PLANTUML_DIAGRAM_HINTS[diagram_type]
    prompt = PLANTUML_CODE_PROMPT.format(diagram_hint=hint, specification=specification)
    return client.chat(
        "You output only valid PlantUML code.",
        prompt,
        temperature=0.2,
    )


def validate_with_vlms(
    image_path: Path,
    specification: str,
    vlm_clients: dict[str, LLMClient],
    weights: dict[str, float],
) -> dict[str, Any]:
    prompt = VLM_SCORING_PROMPT.format(specification=specification)
    scores: dict[str, int] = {}
    for name, client in vlm_clients.items():
        try:
            scores[name] = client.vision_score(image_path, prompt)
        except Exception:
            scores[name] = 0
    composite = weighted_composite(scores, weights)
    return {**scores, "scores": composite}


def run_generation_batch(
    cfg: dict[str, Any],
    diagram_type: str,
    n_samples: int,
    spec_mode: str = "architect",
) -> pd.DataFrame:
    provider = provider_from_env()
    spec_model = __import__("os").environ.get("SPEC_MODEL", "llama3.2:1b")
    code_model = __import__("os").environ.get("CODE_MODEL", "deepseek-r1:32b")

    spec_client = LLMClient(spec_model, provider=provider)
    code_client = LLMClient(code_model, provider=provider)

    jar = Path(cfg["plantuml"]["jar_path"])
    if not jar.is_absolute():
        jar = Path(cfg["root"]) / jar
    img_dir = Path(cfg["data_dir"]) / "images" / diagram_type
    img_dir.mkdir(parents=True, exist_ok=True)

    rows = []
    for _ in tqdm(range(n_samples), desc=f"generate-{diagram_type}"):
        record_id = str(uuid.uuid4())[:8]
        try:
            spec = generate_spec(spec_client, diagram_type, spec_mode)
            reasoning = ""  # optional: parse from code model if using CoT tags
            uml_code = generate_plantuml(code_client, spec, diagram_type)
            img_path, err = render_plantuml(uml_code, img_dir, jar)

            row: dict[str, Any] = {
                "id": record_id,
                "diagram_type": diagram_type,
                "input": spec,
                "reasoning": reasoning,
                "uml_code": uml_code,
                "render_error": err,
            }

            if img_path:
                row["image_path"] = str(img_path)
                vlm_names = __import__("os").environ.get(
                    "VLM_MODELS", "qwen2.5vl:3b,llama3.2-vision:11b,aya-vision:8b"
                ).split(",")
                weight_keys = list(cfg["vlm_weights"].keys())
                vlm_clients = {
                    weight_keys[i]: LLMClient(vlm_names[i].strip(), provider=provider)
                    for i in range(min(len(weight_keys), len(vlm_names)))
                }
                validated = validate_with_vlms(
                    img_path, spec, vlm_clients, cfg["vlm_weights"]
                )
                row.update(validated)
            else:
                row["scores"] = 0.0
                for k in cfg["vlm_weights"]:
                    row[k] = 0

            rows.append(row)
        except Exception as exc:
            rows.append(
                {
                    "id": record_id,
                    "diagram_type": diagram_type,
                    "error": str(exc),
                    "scores": 0,
                }
            )

    return pd.DataFrame(rows)


def save_batch(df: pd.DataFrame, cfg: dict[str, Any], diagram_type: str) -> Path:
    out = Path(cfg["output_dir"]) / f"generated_{diagram_type}.parquet"
    out.parent.mkdir(parents=True, exist_ok=True)
    df.to_parquet(out, index=False)
    jsonl = out.with_suffix(".jsonl")
    df.to_json(jsonl, orient="records", lines=True, force_ascii=False)
    return out

