    """Pull likely domain entity names from NL or mixed text (professional grounding)."""
    names: list[str] = []

    def _add(raw: str) -> None:
        name = re.sub(r"[^A-Za-z0-9_]", "", raw or "")
        if len(name) < 3 or name.lower() in _STOP_ENTITY:
            return
        if name[0].islower():
