    for m in re.finditer(
        r"(?i)\b(?:classes?|entities|components?|packages?|modules?|types?|services?)\b"
        r"[:\s]+([A-Za-z][\w]*(?:\s*,\s*[A-Za-z][\w]*)*(?:\s*,?\s*(?:and|&)\s*[A-Za-z][\w]*)?)",
        text,
    ):
        chunk = m.group(1)
