    for m in re.finditer(
        r"(?i)\b(?:with|including|involving)\s+([A-Z][A-Za-z0-9_]*(?:\s*,\s*[A-Z][A-Za-z0-9_]*)+"
        r"(?:\s*,?\s*(?:and|&)\s*[A-Z][A-Za-z0-9_]*)?)",
