"""Self-adaptation: remember which generators and repairs work, then prefer them.

This is not a second copy of the same prompt. After each run the pipeline records
(diagram type, failure category, strategy, success). Later runs reorder strategies
and may skip a generator that has been losing for that diagram type.
"""

from __future__ import annotations

import json
import threading
from dataclasses import dataclass, field
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

from app.settings import ROOT, get_settings

DEFAULT_MEMORY = ROOT / "data" / "adaptation_memory.json"
_LOCK = threading.Lock()

# Default repair order by failure class (thesis §7).
DEFAULT_STRATEGIES: dict[str, list[str]] = {
    "syntax": ["sanitize_syntax", "spec_rebuild", "llm_targeted"],
    "compile": ["sanitize_syntax", "spec_rebuild", "llm_targeted"],
    "uml_structure": ["sanitize_syntax", "spec_rebuild", "llm_targeted"],
    "missing_element": ["inject_missing", "spec_rebuild", "llm_targeted"],
    "hallucinated_entity": ["strip_hallucinations", "spec_rebuild"],
    "wrong_relationship": ["fix_relationships", "spec_rebuild"],
    "package_hierarchy": ["fix_package_hierarchy", "spec_rebuild"],
    "render": ["sanitize_syntax", "spec_rebuild"],
    "semantic_alignment": ["spec_rebuild", "inject_missing", "strip_hallucinations"],
}

MIN_SAMPLES_TO_ADAPT = 3


def _empty() -> dict[str, Any]:
    return {
        "version": 1,
        "updated_at": None,
        "generators": {},
        "strategies": {},
        "recent": [],
    }


@dataclass
class Rate:
    ok: int = 0
    fail: int = 0

    @property
    def n(self) -> int:
        return self.ok + self.fail

    @property
    def rate(self) -> float:
        return (self.ok + 1) / (self.n + 2)


@dataclass
class AdaptationSession:
    """Per-generation log of policy choices and attempted strategies."""

    diagram_type: str
    events: list[dict[str, Any]] = field(default_factory=list)
    tried_strategies: list[str] = field(default_factory=list)
    generator: str | None = None
    generator_reason: str = ""

    def note(self, **event: Any) -> None:
        event.setdefault("at", datetime.now(timezone.utc).isoformat())
        self.events.append(event)

    def to_dict(self) -> dict[str, Any]:
        return {
            "diagram_type": self.diagram_type,
            "generator": self.generator,
            "generator_reason": self.generator_reason,
            "tried_strategies": list(self.tried_strategies),
            "events": self.events,
        }


class AdaptationMemory:
    def __init__(self, path: Path | None = None):
        self.path = Path(path) if path else Path(get_settings().adaptation_memory_path)
        self._data = _empty()
        self.load()

    def load(self) -> None:
        if self.path.is_file():
            try:
                raw = json.loads(self.path.read_text(encoding="utf-8"))
                if isinstance(raw, dict):
                    self._data = {**_empty(), **raw}
            except (OSError, json.JSONDecodeError):
                self._data = _empty()
        else:
            self._data = _empty()

    def save(self) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self._data["updated_at"] = datetime.now(timezone.utc).isoformat()
        tmp = self.path.with_suffix(".tmp")
        tmp.write_text(json.dumps(self._data, indent=2), encoding="utf-8")
        tmp.replace(self.path)

    def _bucket(self, kind: str, key: str, name: str) -> dict[str, int]:
        root = self._data.setdefault(kind, {})
        group = root.setdefault(key, {})
        cell = group.setdefault(name, {"ok": 0, "fail": 0})
        cell.setdefault("ok", 0)
        cell.setdefault("fail", 0)
        return cell

    def rate(self, kind: str, key: str, name: str) -> Rate:
        cell = self._bucket(kind, key, name)
        return Rate(ok=int(cell.get("ok") or 0), fail=int(cell.get("fail") or 0))

    def record(self, kind: str, key: str, name: str, *, ok: bool, extra: dict[str, Any] | None = None) -> None:
        with _LOCK:
            self.load()
            cell = self._bucket(kind, key, name)
            cell["ok" if ok else "fail"] = int(cell.get("ok" if ok else "fail") or 0) + 1
            rec = {
                "at": datetime.now(timezone.utc).isoformat(),
                "kind": kind,
                "key": key,
                "name": name,
                "ok": ok,
                **(extra or {}),
            }
            recent = list(self._data.get("recent") or [])
            recent.append(rec)
            self._data["recent"] = recent[-80:]
            self.save()

    def snapshot(self) -> dict[str, Any]:
        self.load()
        generators: dict[str, dict[str, Any]] = {}
        for dtype, cells in (self._data.get("generators") or {}).items():
            generators[dtype] = {}
            for name, cell in (cells or {}).items():
                r = Rate(ok=int(cell.get("ok") or 0), fail=int(cell.get("fail") or 0))
                generators[dtype][name] = {"ok": r.ok, "fail": r.fail, "n": r.n, "rate": round(r.rate, 3)}
        strategies: dict[str, dict[str, Any]] = {}
        for key, cells in (self._data.get("strategies") or {}).items():
            strategies[key] = {}
            for name, cell in (cells or {}).items():
                r = Rate(ok=int(cell.get("ok") or 0), fail=int(cell.get("fail") or 0))
                strategies[key][name] = {"ok": r.ok, "fail": r.fail, "n": r.n, "rate": round(r.rate, 3)}
        return {
            "updated_at": self._data.get("updated_at"),
            "generators": generators,
            "strategies": strategies,
            "recent": list(self._data.get("recent") or [])[-20:],
            "policy": {
                "min_samples_to_adapt": MIN_SAMPLES_TO_ADAPT,
                "default_strategies": DEFAULT_STRATEGIES,
            },
        }


def choose_generator(
    diagram_type: str,
    *,
    settings=None,
    memory: AdaptationMemory | None = None,
) -> tuple[str, str]:
    """Pick lora / spec-builder / llm from empirical win rates."""
    settings = settings or get_settings()
    memory = memory or AdaptationMemory()
    dtype = (diagram_type or "class").lower()
    lora_ok = bool(settings.use_finetuned_code) and dtype in {"class", "object", "component", "package"}
    lora = memory.rate("generators", dtype, "lora")
    spec = memory.rate("generators", dtype, "spec-builder")

    # Packages/components historically fail more on free-form LoRA; start grounded
    # until LoRA proves itself.
    if dtype in {"package", "component"} and lora.n < MIN_SAMPLES_TO_ADAPT:
        if lora_ok:
            return (
                "spec-builder",
                f"adapted default: {dtype} starts on spec-builder until LoRA has "
                f"{MIN_SAMPLES_TO_ADAPT} samples (now n={lora.n})",
            )
        return "spec-builder", f"adapted default: grounded {dtype} builder"

    if lora_ok and lora.n >= MIN_SAMPLES_TO_ADAPT and spec.n >= 2 and spec.rate > lora.rate + 0.08:
        return (
            "spec-builder",
            f"adapted: spec-builder rate {spec.rate:.2f} (n={spec.n}) beats "
            f"LoRA {lora.rate:.2f} (n={lora.n}) for {dtype}",
        )
    if lora_ok and lora.n >= 5 and lora.rate < 0.40:
        return (
            "spec-builder",
            f"adapted: LoRA struggling on {dtype} ({lora.rate:.2f}, n={lora.n}); using spec-builder",
        )
    if lora_ok:
        return "lora", f"default: LoRA-first for {dtype} (rate {lora.rate:.2f}, n={lora.n})"
    if settings.mock_providers:
        return "llm", "default: mock provider then spec-builder"
    return "llm", "default: base LLM then spec-builder"


def choose_strategies(
    diagram_type: str,
    category: str,
    *,
    tried: list[str] | None = None,
    memory: AdaptationMemory | None = None,
) -> list[str]:
    """Return unused strategies, empirically successful ones first."""
    memory = memory or AdaptationMemory()
    dtype = (diagram_type or "class").lower()
    cat = (category or "syntax").strip() or "syntax"
    defaults = list(DEFAULT_STRATEGIES.get(cat, ["spec_rebuild", "sanitize_syntax"]))
    tried_set = {t for t in (tried or []) if t}
    key = f"{dtype}|{cat}"

    def sort_key(name: str) -> tuple[float, int]:
        r = memory.rate("strategies", key, name)
        default_idx = defaults.index(name) if name in defaults else 50
        # Enough evidence → rank by win rate; otherwise keep thesis default order.
        if r.n >= MIN_SAMPLES_TO_ADAPT:
            return (-r.rate, default_idx)
        return (0.0, default_idx)

    ordered = sorted(defaults, key=sort_key)
    return [s for s in ordered if s not in tried_set]


def record_generator(diagram_type: str, generator: str, *, ok: bool, memory: AdaptationMemory | None = None) -> None:
    mem = memory or AdaptationMemory()
    mem.record("generators", (diagram_type or "class").lower(), generator, ok=ok, extra={"diagram_type": diagram_type})


def record_strategy(
    diagram_type: str,
    category: str,
    strategy: str,
    *,
    ok: bool,
    memory: AdaptationMemory | None = None,
) -> None:
    mem = memory or AdaptationMemory()
    key = f"{(diagram_type or 'class').lower()}|{(category or 'syntax')}"
    mem.record(
        "strategies",
        key,
        strategy,
        ok=ok,
        extra={"diagram_type": diagram_type, "category": category},
    )


def write_adaptation_sidecar(artifact_dir: Path, session: AdaptationSession) -> Path:
    artifact_dir.mkdir(parents=True, exist_ok=True)
    path = artifact_dir / "adaptation.json"
    path.write_text(json.dumps(session.to_dict(), indent=2), encoding="utf-8")
    return path

"""Category-specific PlantUML repair, ordered by self-adaptation memory."""

from __future__ import annotations

import logging
import re
from dataclasses import dataclass
from typing import Any, Callable

from app.prompts_registry import render_prompt
from app.providers.factory import build_base_code_provider
from app.providers.mock_provider import MockProvider
from app.services.acceptance import (
    FAILURE_COMPILE,
    FAILURE_HALLUCINATION,
    FAILURE_MISSING,
    FAILURE_PACKAGE,
    FAILURE_RELATIONSHIP,
    FAILURE_RENDER,
    FAILURE_SEMANTIC,
    FAILURE_STRUCTURE,
    FAILURE_SYNTAX,
)
from app.services.adaptation import AdaptationMemory, choose_strategies
from app.services.plantuml_from_spec import plantuml_from_spec
from app.services.plantuml_validate import (
    ensure_plantuml_bounds,
    sanitize_plantuml_output,
    validate_diagram,
)
from app.services.traceability import expected_from_requirement
from app.settings import Settings, get_settings
from uml_pipeline.render import extract_plantuml_block

logger = logging.getLogger(__name__)


@dataclass
class RepairResult:
    code: str
    reason: str
    success_validation: bool
    messages: list[str]
    category: str = FAILURE_SYNTAX
    strategy: str = "spec_rebuild"


def _spec_rebuild(spec_json: dict | None, specification: str, diagram_type: str) -> str:
    if spec_json:
        return sanitize_plantuml_output(plantuml_from_spec(spec_json, diagram_type))
    return sanitize_plantuml_output(
        MockProvider()._plantuml(  # noqa: SLF001
            f"Technical specification:\n{specification}",
            diagram_type,
        )
    )


def _close_braces(code: str) -> str:
    text = ensure_plantuml_bounds(code)
    opens = text.count("{")
    closes = text.count("}")
    if opens > closes:
        text = text.replace("@enduml", "") + ("\n}" * (opens - closes)) + "\n@enduml\n"
    return sanitize_plantuml_output(text)


def strategy_sanitize_syntax(code: str, **_: Any) -> str:
    return _close_braces(sanitize_plantuml_output(ensure_plantuml_bounds(code)))


def strategy_spec_rebuild(
    code: str,
    *,
    spec_json: dict | None,
    specification: str,
    diagram_type: str,
    **_: Any,
) -> str:
    return _spec_rebuild(spec_json, specification, diagram_type)


def strategy_inject_missing(
    code: str,
    *,
    spec_json: dict | None,
    specification: str,
    diagram_type: str,
    errors: list[str],
    **_: Any,
) -> str:
    required = expected_from_requirement(specification, spec_json)
    text = ensure_plantuml_bounds(code)
    low = text.lower()
    missing = [n for n in required if n.lower() not in low]
    if not missing:
        return _spec_rebuild(spec_json, specification, diagram_type)
    if len(missing) >= max(3, len(required) // 2):
        return _spec_rebuild(spec_json, specification, diagram_type)
    lines = []
    for name in missing:
        if diagram_type == "package":
            lines.append(f"package {name} {{\n  class {name}\n}}")
        elif diagram_type == "component":
            lines.append(f"[{name}] as {name}")
        elif diagram_type == "object":
            lines.append(f'object "{name}1 : {name}" as {name}1')
        else:
            lines.append(f"class {name}")
    if len(missing) >= 2:
        a, b = missing[0], missing[1]
        if diagram_type == "package":
            lines.append(f"{a} ..> {b}")
        else:
            lines.append(f"{a} --> {b}")
    injected = text.replace("@enduml", "\n".join(lines) + "\n@enduml", 1)
    return sanitize_plantuml_output(injected)


def strategy_strip_hallucinations(
    code: str,
    *,
    spec_json: dict | None,
    specification: str,
    **_: Any,
) -> str:
    keep = {n.lower() for n in expected_from_requirement(specification, spec_json)}
    if not keep:
        return sanitize_plantuml_output(ensure_plantuml_bounds(code))
    text = ensure_plantuml_bounds(code)
    drop: list[str] = []
    for m in re.finditer(
        r"(?im)^\s*(?:abstract\s+)?(?:class|interface|enum|package|object|component)\s+"
        r"(?:\"([^\"]+)\"\s+as\s+)?([A-Za-z_][\w]*)",
        text,
    ):
        name = (m.group(2) or m.group(1) or "").strip()
        if name and name.lower() not in keep and not any(name.lower().startswith(k) for k in keep):
            drop.append(name)
    for m in re.finditer(r"(?im)^\s*\[([^\]]+)\]", text):
        raw = re.sub(r"\s+as\s+\S+$", "", m.group(1)).strip()
        token = re.sub(r"[^\w]", "_", raw.split()[0]) if raw else ""
        if token and token.lower() not in keep:
            drop.append(token)
    out = text
    for name in dict.fromkeys(drop):
        out = re.sub(
            rf"(?ims)^\s*(?:abstract\s+)?class\s+{re.escape(name)}\b[^\n]*\{{.*?^\s*\}}\s*\n",
            "",
            out,
        )
        out = re.sub(rf"(?im)^\s*(?:abstract\s+)?(?:class|interface|enum|package|object)\s+{re.escape(name)}\b[^\n]*\n", "", out)
        out = re.sub(rf"(?im)^\s*package\s+{re.escape(name)}\s*\{{[\s\S]*?^\}}\s*\n", "", out)
        out = re.sub(rf"(?im)^.*\b{re.escape(name)}\b.*(?:-->|\.\.>|\*--|o--|--\|>|\+\-\-).*\n", "", out)
    return sanitize_plantuml_output(out)


def strategy_fix_relationships(
    code: str,
    *,
    spec_json: dict | None,
    specification: str,
    diagram_type: str,
    **_: Any,
) -> str:
    rebuilt = _spec_rebuild(spec_json, specification, diagram_type)
    # Keep existing type declarations; replace only connector lines from the spec builder.
    decls = [
        ln
        for ln in ensure_plantuml_bounds(code).splitlines()
        if not re.search(r"(-->|\.\.>|\*--|o--|--\|>|<\|--|..\|>|\+\-\-)", ln)
        and ln.strip().lower() not in {"@startuml", "@enduml"}
        and not ln.strip().lower().startswith("title ")
    ]
    rels = [
        ln
        for ln in rebuilt.splitlines()
        if re.search(r"(-->|\.\.>|\*--|o--|--\|>|<\|--|..\|>|\+\-\-)", ln)
    ]
    if not decls:
        return rebuilt
    lines = ["@startuml", *decls, *rels, "@enduml"]
    return sanitize_plantuml_output("\n".join(lines) + "\n")


def strategy_fix_package_hierarchy(
    code: str,
    *,
    spec_json: dict | None,
    specification: str,
    diagram_type: str,
    **_: Any,
) -> str:
    return _spec_rebuild(spec_json, specification, "package" if diagram_type == "package" else diagram_type)


def strategy_llm_targeted(
    code: str,
    *,
    specification: str,
    diagram_type: str,
    errors: list[str],
    repair_notes: str,
    category: str,
    settings: Settings,
    spec_json: dict | None,
    **_: Any,
) -> str:
    provider = build_base_code_provider(settings)
    ref, prompt = render_prompt(
        "repair_plantuml",
        "v1",
        diagram_type=diagram_type,
        specification=specification,
        plantuml=code,
        errors="\n".join(errors) or "(none)",
        repair_notes=(repair_notes or "(none)") + f"\nfailure_category={category}",
    )
    system = (
        f"You output only valid PlantUML for a {diagram_type} diagram. "
        f"Failure category: {category}. Fix ONLY that class of error using the listed messages. "
        "Do not invent entities that are absent from the specification. "
        "Never convert to a different diagram type."
    )
    try:
        raw = provider.chat(system, prompt, temperature=0.1)
        return sanitize_plantuml_output(ensure_plantuml_bounds(extract_plantuml_block(raw)))
    except Exception as exc:
        logger.warning("Targeted LLM repair failed (%s)", exc)
        return _spec_rebuild(spec_json, specification, diagram_type)


_STRATEGIES: dict[str, Callable[..., str]] = {
    "sanitize_syntax": strategy_sanitize_syntax,
    "spec_rebuild": strategy_spec_rebuild,
    "inject_missing": strategy_inject_missing,
    "strip_hallucinations": strategy_strip_hallucinations,
    "fix_relationships": strategy_fix_relationships,
    "fix_package_hierarchy": strategy_fix_package_hierarchy,
    "llm_targeted": strategy_llm_targeted,
}


def repair_plantuml(
    plantuml: str,
    specification: str,
    diagram_type: str,
    errors: list[str],
    repair_notes: str = "",
    settings: Settings | None = None,
    *,
    category: str | None = None,
    spec_json: dict | None = None,
    tried: list[str] | None = None,
    memory: AdaptationMemory | None = None,
) -> RepairResult:
    """Run the next unused strategy for this failure category (not a blind regenerate)."""
    settings = settings or get_settings()
    cat = (category or FAILURE_SYNTAX).strip() or FAILURE_SYNTAX
    errors = [e for e in (errors or []) if e]
    memory = memory or AdaptationMemory()
    order = choose_strategies(diagram_type, cat, tried=tried, memory=memory)
    if not order:
        order = ["spec_rebuild"]

    kwargs = {
        "spec_json": spec_json,
        "specification": specification,
        "diagram_type": diagram_type,
        "errors": errors,
        "repair_notes": repair_notes,
        "category": cat,
        "settings": settings,
    }

    last = RepairResult(
        code=ensure_plantuml_bounds(plantuml),
        reason="no strategy applied",
        success_validation=False,
        messages=errors,
        category=cat,
        strategy=order[0],
    )
    for name in order:
        fn = _STRATEGIES.get(name, strategy_spec_rebuild)
        try:
            fixed = fn(plantuml, **kwargs)
        except Exception as exc:
            logger.warning("Strategy %s failed: %s", name, exc)
            continue
        validation = validate_diagram(fixed, diagram_type)
        last = RepairResult(
            code=fixed,
            reason=f"{cat} → {name}: {'; '.join(errors[:2]) or 'n/a'}",
            success_validation=validation.ok,
            messages=validation.messages,
            category=cat,
            strategy=name,
        )
        # One strategy per call so the next loop can pick the next unused one.
        return last
    return last

